{
  "name": "pi-posthog-llm-gateway",
  "version": "0.1.0",
  "description": "Use PostHog's LLM gateway (Claude + GPT, billed through PostHog) as a provider in the pi coding agent, authenticated via PostHog OAuth.",
  "keywords": [
    "pi-package",
    "pi",
    "posthog",
    "llm",
    "gateway",
    "oauth",
    "anthropic",
    "openai"
  ],
  "license": "MIT",
  "type": "module",
  "author": "PostHog",
  "repository": {
    "type": "git",
    "url": "https://github.com/PostHog/pi-posthog-llm-gateway"
  },
  "pi": {
    "extensions": [
      "./src/index.ts"
    ]
  },
  "peerDependencies": {
    "@earendil-works/pi-ai": "*",
    "@earendil-works/pi-coding-agent": "*"
  },
  "devDependencies": {
    "@earendil-works/pi-ai": "0.80.3",
    "@earendil-works/pi-coding-agent": "0.80.3",
    "@types/node": "^24.0.0",
    "typescript": "^5.6.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  }
}

/**
 * PostHog OAuth for the pi gateway provider.
 *
 * Implements pi's OAuthProviderInterface (minus `id`, which pi fills from the
 * provider name). The flow is authorization-code + PKCE (S256) against
 * PostHog's django-oauth-toolkit server, using the PUBLIC `array`/`posthog_code`
 * client id (no secret) and a loopback redirect on a registered port. This is
 * the same OAuth app PostHog's own desktop coding agent uses, so the resulting
 * `pha_` access token is authorized for the gateway's `posthog_code` product.
 *
 * Modelled on pi-ai's built-in `openaiCodexOAuthProvider` (browser callback
 * server raced against manual paste). Uses only Node built-ins so it has no
 * runtime dependencies.
 */
import { createHash, randomBytes } from "node:crypto";
import { createServer, type Server } from "node:http";
import type { Api, Model } from "@earendil-works/pi-ai/compat";
import type { OAuthCredentials, OAuthLoginCallbacks } from "@earendil-works/pi-ai";
import {
    anthropicBaseUrl,
    asRegion,
    defaultRegion,
    envRegion,
    openaiBaseUrl,
    type Region,
    type ResolvedConfig,
    resolveConfig,
} from "./config";

/** Loopback ports registered as redirect URIs for the array/posthog_code app
 * (`setup_background_agents.py`: http://localhost:{8237,8239}/callback). */
const REDIRECT_PORTS = [8237, 8239];
const CALLBACK_PATH = "/callback";

interface TokenResponse {
    access_token?: string;
    refresh_token?: string;
    expires_in?: number;
    scope?: string;
    posthog_region?: string;
}

function generatePkce(): { verifier: string; challenge: string } {
    const verifier = randomBytes(32).toString("base64url");
    const challenge = createHash("sha256").update(verifier).digest("base64url");
    return { verifier, challenge };
}

const HTML_HEADERS = { "Content-Type": "text/html; charset=utf-8" };

function escapeHtml(value: string): string {
    return value.replace(
        /[&<>"']/g,
        (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c] as string,
    );
}

function resultPage(title: string, message: string): string {
    return `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title></head>
<body style="font-family:system-ui,sans-serif;max-width:34rem;margin:4rem auto;padding:0 1rem;text-align:center">
<h1>${escapeHtml(title)}</h1><p>${escapeHtml(message)}</p>
<script>setTimeout(function(){window.close()},1500)</script></body></html>`;
}

interface CallbackServer {
    redirectUri: string;
    close(): void;
    cancelWait(): void;
    waitForCode(): Promise<{ code?: string } | null>;
}

/** Bind a loopback callback server on the first available registered port. */
async function startCallbackServer(state: string): Promise<CallbackServer> {
    let lastError: unknown;
    for (const port of REDIRECT_PORTS) {
        try {
            return await listenOnPort(port, state);
        } catch (error) {
            lastError = error;
            if ((error as NodeJS.ErrnoException)?.code === "EADDRINUSE") continue;
            throw error;
        }
    }
    const detail = lastError instanceof Error ? `: ${lastError.message}` : "";
    throw new Error(
        `Could not start the OAuth callback server on ports ${REDIRECT_PORTS.join(", ")}. ` +
            `Free one of them and run /login again${detail}`,
    );
}

function listenOnPort(port: number, state: string): Promise<CallbackServer> {
    return new Promise<CallbackServer>((resolve, reject) => {
        let settle: (value: { code?: string } | null) => void = () => {};
        const codePromise = new Promise<{ code?: string } | null>((res) => {
            let done = false;
            settle = (value) => {
                if (done) return;
                done = true;
                res(value);
            };
        });

        const server: Server = createServer((req, res) => {
            const url = new URL(req.url ?? "", `http://localhost:${port}`);
            if (url.pathname !== CALLBACK_PATH) {
                res.writeHead(404, HTML_HEADERS);
                res.end(resultPage("Not found", "This is not the OAuth callback endpoint."));
                return;
            }
            const error = url.searchParams.get("error");
            if (error) {
                const description = url.searchParams.get("error_description") ?? error;
                res.writeHead(400, HTML_HEADERS);
                res.end(resultPage("Authorization failed", description));
                settle({});
                return;
            }
            if (url.searchParams.get("state") !== state) {
                res.writeHead(400, HTML_HEADERS);
                res.end(resultPage("Authorization failed", "State mismatch — please run /login again."));
                return;
            }
            const code = url.searchParams.get("code") ?? undefined;
            if (!code) {
                res.writeHead(400, HTML_HEADERS);
                res.end(resultPage("Authorization failed", "No authorization code was returned."));
                return;
            }
            res.writeHead(200, HTML_HEADERS);
            res.end(resultPage("PostHog login complete", "You can close this tab and return to your terminal."));
            settle({ code });
        });

        server.once("error", reject);
        server.listen(port, () => {
            server.removeListener("error", reject);
            resolve({
                redirectUri: `http://localhost:${port}${CALLBACK_PATH}`,
                close: () => {
                    try {
                        server.close();
                    } catch {
                        /* already closed */
                    }
                },
                cancelWait: () => settle(null),
                waitForCode: () => codePromise,
            });
        });
    });
}

function buildAuthorizeUrl(
    cfg: ResolvedConfig,
    redirectUri: string,
    challenge: string,
    state: string,
): string {
    const url = new URL(`${cfg.oauthBaseUrl}/oauth/authorize`);
    url.searchParams.set("response_type", "code");
    url.searchParams.set("client_id", cfg.clientId);
    url.searchParams.set("redirect_uri", redirectUri);
    url.searchParams.set("scope", cfg.scope);
    url.searchParams.set("code_challenge", challenge);
    url.searchParams.set("code_challenge_method", "S256");
    url.searchParams.set("state", state);
    return url.toString();
}

function truncate(text: string, max = 300): string {
    const clean = text.replace(/\s+/g, " ").trim();
    return clean.length > max ? `${clean.slice(0, max)}…` : clean;
}

async function toCredentials(
    response: Response,
    region: Region,
    operation: string,
    fallbackRefresh?: string,
): Promise<OAuthCredentials> {
    if (!response.ok) {
        const body = await response.text().catch(() => "");
        throw new Error(`PostHog OAuth ${operation} failed (HTTP ${response.status})${body ? `: ${truncate(body)}` : ""}`);
    }
    const json = (await response.json().catch(() => ({}))) as TokenResponse;
    if (!json.access_token) {
        throw new Error(`PostHog OAuth ${operation} returned no access_token`);
    }
    const refresh = json.refresh_token ?? fallbackRefresh;
    if (!refresh) {
        throw new Error(`PostHog OAuth ${operation} returned no refresh_token`);
    }
    const expiresInSeconds = typeof json.expires_in === "number" ? json.expires_in : 3600;
    return {
        access: json.access_token,
        refresh,
        expires: Date.now() + expiresInSeconds * 1000,
        // Stored on the credential (OAuthCredentials has an index signature) so
        // refresh + modifyModels re-resolve the right region on later runs.
        region,
    };
}

async function exchangeAuthorizationCode(
    cfg: ResolvedConfig,
    code: string,
    verifier: string,
    redirectUri: string,
    signal?: AbortSignal,
): Promise<OAuthCredentials> {
    const response = await fetch(`${cfg.oauthBaseUrl}/oauth/token`, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
        body: new URLSearchParams({
            grant_type: "authorization_code",
            code,
            redirect_uri: redirectUri,
            client_id: cfg.clientId,
            code_verifier: verifier,
        }),
        signal,
    });
    return toCredentials(response, cfg.region, "code exchange");
}

async function refreshAccessToken(cfg: ResolvedConfig, refreshToken: string): Promise<OAuthCredentials> {
    const response = await fetch(`${cfg.oauthBaseUrl}/oauth/token`, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
        body: new URLSearchParams({
            grant_type: "refresh_token",
            refresh_token: refreshToken,
            client_id: cfg.clientId,
        }),
    });
    // Refresh tokens rotate; keep the old one only if the server omits a new one.
    return toCredentials(response, cfg.region, "token refresh", refreshToken);
}

async function chooseRegion(callbacks: OAuthLoginCallbacks): Promise<Region> {
    const fromEnv = envRegion();
    if (fromEnv) return fromEnv;
    const choice = await callbacks.onSelect({
        message: "Which PostHog region is your account in?",
        options: [
            { id: "us", label: "US · us.posthog.com" },
            { id: "eu", label: "EU · eu.posthog.com" },
            { id: "dev", label: "Local dev · localhost:8010" },
        ],
    });
    const region = asRegion(choice);
    if (!region) throw new Error("Login cancelled");
    return region;
}

/** Extract an authorization code from a bare code, a full redirect URL, or a
 * pasted query string, validating `state` when present. */
function parseAuthorizationInput(input: string, state: string): string {
    const value = input.trim();
    if (!value) throw new Error("No authorization code provided");
    try {
        const url = new URL(value);
        const returnedState = url.searchParams.get("state");
        if (returnedState && returnedState !== state) throw new Error("State mismatch");
        const code = url.searchParams.get("code");
        if (code) return code;
    } catch (error) {
        if (error instanceof Error && error.message === "State mismatch") throw error;
        // Not a URL — fall through to looser parsing.
    }
    const match = value.match(/[?&]code=([^&\s]+)/);
    if (match) return decodeURIComponent(match[1]);
    if (!/\s/.test(value)) return value; // bare code
    throw new Error("Could not find an authorization code in the pasted text");
}

/** Race the local callback server against manual paste (headless fallback). */
async function obtainCode(server: CallbackServer, callbacks: OAuthLoginCallbacks, state: string): Promise<string> {
    let code: string | undefined;

    if (callbacks.onManualCodeInput) {
        let manual: string | undefined;
        let manualError: Error | undefined;
        const manualPromise = callbacks
            .onManualCodeInput()
            .then((input) => {
                manual = input;
                server.cancelWait();
            })
            .catch((error) => {
                manualError = error instanceof Error ? error : new Error(String(error));
                server.cancelWait();
            });

        const result = await server.waitForCode();
        if (manualError) throw manualError;
        if (result?.code) code = result.code;
        else if (manual) code = parseAuthorizationInput(manual, state);

        if (!code) {
            await manualPromise;
            if (manualError) throw manualError;
            if (manual) code = parseAuthorizationInput(manual, state);
        }
    } else {
        const result = await server.waitForCode();
        if (result?.code) code = result.code;
        if (!code) {
            const input = await callbacks.onPrompt({
                message: "Paste the authorization code (or the full redirect URL):",
            });
            code = parseAuthorizationInput(input, state);
        }
    }

    if (!code) throw new Error("Login was cancelled or no authorization code was received");
    return code;
}

/**
 * The oauth object passed to `pi.registerProvider(..., { oauth })`. `id` is set
 * by pi from the provider name. `usesCallbackServer` tells pi to offer the
 * manual-paste input alongside the browser flow.
 */
export function createPosthogOAuth() {
    return {
        name: "PostHog",
        usesCallbackServer: true,

        async login(callbacks: OAuthLoginCallbacks): Promise<OAuthCredentials> {
            const region = await chooseRegion(callbacks);
            const cfg = resolveConfig(region);
            const { verifier, challenge } = generatePkce();
            const state = randomBytes(16).toString("hex");
            const server = await startCallbackServer(state);
            try {
                const authorizeUrl = buildAuthorizeUrl(cfg, server.redirectUri, challenge, state);
                callbacks.onAuth({
                    url: authorizeUrl,
                    instructions:
                        "Complete the PostHog login in your browser to authorize pi. The tab closes automatically.",
                });
                callbacks.onProgress?.("Waiting for PostHog authorization…");
                const code = await obtainCode(server, callbacks, state);
                callbacks.onProgress?.("Exchanging authorization code…");
                return await exchangeAuthorizationCode(cfg, code, verifier, server.redirectUri, callbacks.signal);
            } finally {
                server.close();
            }
        },

        async refreshToken(credentials: OAuthCredentials): Promise<OAuthCredentials> {
            if (!credentials.refresh) throw new Error("No refresh token stored — run /login again.");
            const region = asRegion(credentials.region) ?? defaultRegion();
            return refreshAccessToken(resolveConfig(region), credentials.refresh);
        },

        getApiKey(credentials: OAuthCredentials): string {
            return credentials.access;
        },

        /** Point each model at the logged-in region's gateway host. Claude uses
         * the Anthropic base, GPT the OpenAI base. */
        modifyModels(models: Model<Api>[], credentials: OAuthCredentials): Model<Api>[] {
            const region = asRegion(credentials.region) ?? defaultRegion();
            const { gatewayBaseUrl } = resolveConfig(region);
            const anthropic = anthropicBaseUrl(gatewayBaseUrl);
            const openai = openaiBaseUrl(gatewayBaseUrl);
            return models.map((model) => ({
                ...model,
                baseUrl: model.api === "anthropic-messages" ? anthropic : openai,
            }));
        },
    };
}

/**
 * pi extension: register PostHog's LLM gateway as a provider.
 *
 * Adds a `posthog` provider whose models (Claude + GPT) are served by PostHog's
 * LLM gateway and billed through PostHog under the `posthog_code` product.
 * Authentication is PostHog OAuth (`/login posthog`); no API keys to manage.
 *
 * Region and endpoints are resolved from `POSTHOG_GATEWAY_REGION` (default `us`)
 * with optional overrides (see src/config.ts). The region is finalized at login
 * and stored on the credential, so `oauth.modifyModels` re-points models at the
 * correct gateway host regardless of the factory-time default.
 */
import type { ExtensionAPI, ProviderConfig } from "@earendil-works/pi-coding-agent";
import { anthropicBaseUrl, defaultRegion, openaiBaseUrl, PRODUCT, resolveConfig } from "./config";
import { buildModels } from "./models";
import { createPosthogOAuth } from "./oauth";

/** Provider id: users run `/login posthog` and see these models under it in `/model`. */
const PROVIDER = "posthog";

export default function posthogGatewayExtension(pi: ExtensionAPI): void {
    const { gatewayBaseUrl } = resolveConfig(defaultRegion());
    const anthropicBase = anthropicBaseUrl(gatewayBaseUrl);
    const openaiBase = openaiBaseUrl(gatewayBaseUrl);

    const config: ProviderConfig = {
        name: "PostHog LLM Gateway",
        // Provider default: Claude models go to the Anthropic Messages endpoint.
        // GPT models carry their own `api`/`baseUrl` overrides (see buildModels).
        api: "anthropic-messages",
        baseUrl: anthropicBase,
        models: buildModels(anthropicBase, openaiBase),
        oauth: createPosthogOAuth(),
    };

    pi.registerProvider(PROVIDER, config);

    // Diagnostic: print the resolved region, endpoints, and model ids.
    pi.registerCommand("posthog-gateway", {
        description: "Show PostHog LLM gateway status (region, endpoints, models)",
        handler: async (_args, ctx) => {
            const cfg = resolveConfig(defaultRegion());
            const models = buildModels(
                anthropicBaseUrl(cfg.gatewayBaseUrl),
                openaiBaseUrl(cfg.gatewayBaseUrl),
            );
            const summary = [
                `PostHog LLM gateway — provider "${PROVIDER}", product "${PRODUCT}"`,
                `Region:  ${cfg.region}`,
                `Gateway: ${cfg.gatewayBaseUrl}`,
                `OAuth:   ${cfg.oauthBaseUrl}`,
                `Models:  ${models.map((m) => m.id).join(", ")}`,
                "",
                `Log in:  /login ${PROVIDER}    ·    Pick a model: /model`,
            ].join("\n");
            if (ctx.hasUI) {
                ctx.ui.notify(summary, "info");
            }
        },
    });
}

/**
 * Region + endpoint resolution for the PostHog LLM gateway provider.
 *
 * Everything a user might need to point this at US, EU, or a local/self-hosted
 * PostHog is derived from one region plus optional env overrides. The region is
 * chosen at login time (env var or interactive prompt) and stored on the OAuth
 * credential, so later runs re-resolve hosts from the stored region — picking up
 * any env overrides live.
 */

/** PostHog deployment region. `dev` targets a local hogli/phrocs stack. */
export type Region = "us" | "eu" | "dev";

export const REGIONS: readonly Region[] = ["us", "eu", "dev"];

/** The gateway product this extension authenticates as. Aliased `array`/`twig`.
 * OAuth-only; every generation is metered under `ai_product = posthog_code`. */
export const PRODUCT = "posthog_code";

/** Per-region defaults: OAuth host, the public `array`/`posthog_code` client id
 * (a PUBLIC OAuth client — no secret), the gateway host, and the scope to
 * request at `/oauth/authorize`.
 *
 * Scope differs by environment because it is validated against the app's scope
 * ceiling (posthog/scopes.py `scopes_within_ceiling`):
 *  - Prod US/EU apps have a non-empty ceiling, where `*` is never grantable and
 *    only listed scopes pass → request `llm_gateway:read` (the scope the gateway
 *    checks for and the one PostHog mints on this app in code_usage_gate.py).
 *  - The dev app is seeded with an empty ceiling (setup_background_agents.py),
 *    where `llm_gateway:read` (a privileged scope) is rejected but `*` is
 *    grandfathered in → request `*`.
 * Override for any region with `POSTHOG_OAUTH_SCOPE` (e.g. a dedicated app that
 * carries `llm_gateway:read` on its ceiling).
 *
 * Client ids: posthog/posthog `posthog/temporal/oauth.py` (ARRAY_APP_CLIENT_ID_*).
 * Gateway hosts: `services/llm-gateway` (gateway.<region>.posthog.com). */
const REGION_DEFAULTS: Record<Region, { oauthBaseUrl: string; clientId: string; gatewayBaseUrl: string; scope: string }> = {
    us: {
        oauthBaseUrl: "https://us.posthog.com",
        clientId: "HCWoE0aRFMYxIxFNTTwkOORn5LBjOt2GVDzwSw5W",
        gatewayBaseUrl: "https://gateway.us.posthog.com",
        scope: "llm_gateway:read",
    },
    eu: {
        oauthBaseUrl: "https://eu.posthog.com",
        clientId: "AIvijgMS0dxKEmr5z6odvRd8Pkh5vts3nPTzgzU9",
        gatewayBaseUrl: "https://gateway.eu.posthog.com",
        scope: "llm_gateway:read",
    },
    dev: {
        oauthBaseUrl: "http://localhost:8010",
        clientId: "DC5uRLVbGI02YQ82grxgnK6Qn12SXWpCqdPb60oZ",
        gatewayBaseUrl: "http://localhost:3308",
        scope: "*",
    },
};

/** Fully-resolved endpoints for a login/request. */
export interface ResolvedConfig {
    region: Region;
    /** OAuth authorization server base, e.g. `https://us.posthog.com`. */
    oauthBaseUrl: string;
    /** Public OAuth client id used for the authorization-code + PKCE flow. */
    clientId: string;
    /** Gateway host, e.g. `https://gateway.us.posthog.com`. */
    gatewayBaseUrl: string;
    /** Scope requested at `/oauth/authorize` for this region. */
    scope: string;
}

function env(name: string): string | undefined {
    const value = process.env[name];
    return value && value.trim() ? value.trim() : undefined;
}

/** Region from `POSTHOG_GATEWAY_REGION`, or undefined if unset/invalid. */
export function envRegion(): Region | undefined {
    const raw = env("POSTHOG_GATEWAY_REGION")?.toLowerCase();
    return (REGIONS as readonly string[]).includes(raw ?? "") ? (raw as Region) : undefined;
}

/**
 * Resolve endpoints for a region, layering optional env overrides on top:
 * `POSTHOG_OAUTH_BASE_URL`, `POSTHOG_OAUTH_CLIENT_ID` (⇐ swap in a dedicated
 * OAuth app here), `POSTHOG_GATEWAY_BASE_URL`, `POSTHOG_OAUTH_SCOPE`.
 */
export function resolveConfig(region: Region): ResolvedConfig {
    const base = REGION_DEFAULTS[region];
    return {
        region,
        oauthBaseUrl: (env("POSTHOG_OAUTH_BASE_URL") ?? base.oauthBaseUrl).replace(/\/+$/, ""),
        clientId: env("POSTHOG_OAUTH_CLIENT_ID") ?? base.clientId,
        gatewayBaseUrl: (env("POSTHOG_GATEWAY_BASE_URL") ?? base.gatewayBaseUrl).replace(/\/+$/, ""),
        scope: env("POSTHOG_OAUTH_SCOPE") ?? base.scope,
    };
}

/** Coerce an unknown value (e.g. a stored credential field) to a valid Region. */
export function asRegion(value: unknown): Region | undefined {
    return typeof value === "string" && (REGIONS as readonly string[]).includes(value) ? (value as Region) : undefined;
}

/** Region to assume when none is stored/configured. */
export function defaultRegion(): Region {
    return envRegion() ?? "us";
}

/**
 * Base URL for the Anthropic Messages API. pi's `anthropic-messages` client
 * appends `/v1/messages`, so this must be the product root (no `/v1`).
 * → `https://gateway.us.posthog.com/posthog_code/v1/messages`
 */
export function anthropicBaseUrl(gatewayBaseUrl: string): string {
    return `${gatewayBaseUrl}/${PRODUCT}`;
}

/**
 * Base URL for the OpenAI Chat Completions API. pi's `openai-completions`
 * client appends `chat/completions` to a `/v1` base.
 * → `https://gateway.us.posthog.com/posthog_code/v1/chat/completions`
 */
export function openaiBaseUrl(gatewayBaseUrl: string): string {
    return `${gatewayBaseUrl}/${PRODUCT}/v1`;
}
